                q=[(r,c)]; seen[r][c]=1; cs=[]
                while q:
                    a,b=q.pop(); cs.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==color and not seen[x][y]:
                                seen[x][y]=1; q.append((x,y))
                out.append(cs)
