def norm(cs):
    rs=[a for a,b in cs]; cs_=[b for a,b in cs]
    mr,mc=min(rs),min(cs_)
    base=((np.array(a-mr,c-mc) for a in rs) for c in cs_) # placeholder
    pts=sorted((a-mr,c-mc) for a,b in sorted(set(cs)))
    m=max(p[0] for p in pts); n=max(p[1] for p in pts)
    grid=[[0]*(n+1) for _ in range(m+1)]
    for a,b in pts: grid[a][b]=1
    t=tuple(tuple(r) for r in grid)
