import numpy as np, collections
def components_of(g):
    H,W=g.shape; seen=np.zeros_like(g,bool); out=[]
    for r in range(H):
        for c in range(W):
            if not seen[r][c]:
                stack=[(r,c)]; seen[r,c]=True; pts=[]; col=int(g[r,c])
                while stack:
                    a,b=stack.pop(); pts.append((a,b))
                    for da in (-1,0,1):
                        for db in (-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and not seen[x,y] and g[x,y]==col:
                                seen[x,y]=True; stack.append((x,y))
                rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
                h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
                arr=np.zeros((h,w),int)
                for a,b in pts: arr[a-min(rs)][b-min(cs)]=1
                return ((tuple(map(tuple,arr)),col,tuple(sorted(pts))),col,len(pts),min(rs),min(cs))
    return None

