    g=np.array(g); H,W=g.shape; seen=np.zeros_like(g,bool); out=[]
    for r in range(H):
        for c in range(W):
            if not seen[r,c]:
                col=int(g[r,c]); stack=[(r,c)]; seen[r,c]=True; pts=[]
                while stack:
                    a,b=stack.pop(); pts.append((a,b))
                    for da in (-1,0,1):
                        for db in (-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and not seen[x,y] and int(g[x,y])==col:
                                seen[x,y]=True; stack.append((x,y))
                arr=np.zeros((max(p[0] for p in pts)-min(p[0] for p in pts)+1, max(p[1] for p in pts)-min(p[1] for p in pts)+1), int)
                for a,b in pts: arr[a-min(p[0] for p in pts)][b-min(p[1] for p in pts)]=1
                key=tuple(map(tuple,arr.tolist()))
                out.append({'key':key,'col':int(col),'n':len(pts),'pos':(min(p[0] for p in pts),min(p[1] for p in pts)), 'pts':set(pts)})
    return out

